"use strict";(globalThis.webpackChunklithos_webdocs=globalThis.webpackChunklithos_webdocs||[]).push([[5717],{9608:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>f,contentTitle:()=>m,default:()=>k,frontMatter:()=>b,metadata:()=>n,toc:()=>y});const n=JSON.parse('{"id":"lithosapi/get-mining-totals","title":"Mining and payment totals","description":"Running totals over the retained history: Lithos blocks, payout rewards, bond refunds,","source":"@site/docs/lithosapi/get-mining-totals.api.mdx","sourceDirName":"lithosapi","slug":"/lithosapi/get-mining-totals","permalink":"/assets/docs/lithosapi/get-mining-totals","draft":false,"unlisted":false,"editUrl":null,"tags":[],"version":"current","frontMatter":{"id":"get-mining-totals","title":"Mining and payment totals","description":"Running totals over the retained history: Lithos blocks, payout rewards, bond refunds,","sidebar_label":"Mining and payment totals","hide_title":true,"hide_table_of_contents":true,"api":"","sidebar_class_name":"get api-method","info_path":"docs/lithosapi/lithos-client-api","custom_edit_url":null},"sidebar":"openApiSidebar","previous":{"title":"Statistics overview","permalink":"/assets/docs/lithosapi/get-stats"},"next":{"title":"Mining statistics by hour or day","permalink":"/assets/docs/lithosapi/get-mining-buckets"}}');var i=o(74848),s=o(28453),a=o(33617),r=o.n(a),l=o(17543),d=o.n(l),c=o(86013),h=o.n(c),p=o(63723),u=o.n(p),g=(o(18766),o(79329),o(9303));const b={id:"get-mining-totals",title:"Mining and payment totals",description:"Running totals over the retained history: Lithos blocks, payout rewards, bond refunds,",sidebar_label:"Mining and payment totals",hide_title:!0,hide_table_of_contents:!0,api:"",sidebar_class_name:"get api-method",info_path:"docs/lithosapi/lithos-client-api",custom_edit_url:null},m=void 0,f={},y=[];function w(e){const t={code:"code",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(g.default,{as:"h1",className:"openapi__heading",children:"Mining and payment totals"}),"\n",(0,i.jsx)(r(),{method:"get",path:"/stats/mining/totals",context:"endpoint"}),"\n",(0,i.jsxs)(t.p,{children:["Running totals over the retained history: Lithos blocks, payout rewards, bond refunds,\ntransaction fees, batching revenue, participation and confirmed fraud proofs. Keys under\n",(0,i.jsx)(t.code,{children:"local."})," belong to this client's primary mining address; ",(0,i.jsx)(t.code,{children:"network."})," keys cover the whole\nconfigured protocol."]}),"\n",(0,i.jsxs)(t.p,{children:["Label the period with the height and timestamp fields. Retention holds a rollback buffer\nand can run behind on pruning, so the period is often longer than the configured number\nof days. Only ",(0,i.jsx)(t.code,{children:"ready"})," means collection reached the last checked chain tip \u2014 a loading or\ndisabled response can return an empty ",(0,i.jsx)(t.code,{children:"totals"})," map, which is not evidence that nothing\nhappened. Reorgs and pruning can lower a total between two requests."]}),"\n",(0,i.jsx)(d(),{parameters:void 0}),"\n",(0,i.jsx)(h(),{title:"Body",body:void 0}),"\n",(0,i.jsx)(u(),{id:void 0,label:void 0,responses:{200:{description:"The last published totals, with collection status and coverage.",content:{"application/json":{schema:{type:"object",required:["status","persistent","totals"],properties:{status:{type:"string",enum:["disabled","loading","ready","stale","unavailable","catching-up","recovering"],description:"How far collection has got. `ready` means it reached the last checked chain tip. `catching-up` and `recovering` mean replay or reorg work is still running, `stale` means the last successful check is too old, and `unavailable` means collection failed. On `disabled` or `loading` the numbers are not evidence that the period was quiet.",title:"MiningCollectionStatus"},persistent:{type:"boolean",description:"Whether history survives a client restart."},observedAt:{type:"integer",format:"int64",description:"When the last replay cycle started, in Unix milliseconds. Absent until the first check after a restart."},sourceHeight:{type:"integer",description:"Last processed height, or the starting anchor if nothing has been collected yet."},sourceBlockId:{type:"string",description:"The block id at `sourceHeight`."},targetHeight:{type:"integer",description:"Last checked chain height. Collection can lag behind it."},fromHeight:{type:"integer",description:"First retained height. Higher than `sourceHeight` means the history is empty."},fromTimestamp:{type:"integer",format:"int64",description:"Timestamp of the first retained block, in Unix milliseconds. Absent when there are no block records."},totals:{type:"object",additionalProperties:{type:"string",pattern:"^[0-9]+$",description:"An exact nonnegative integer as a decimal string. Parse it without going through a float.",example:"1000000000",title:"StatsInteger"},description:"Exact sums and counts for the period, as decimal strings. A missing key means nothing was\ncollected for it, which is not evidence that nothing happened outside the coverage. Amounts\nending in `NanoErg` are nanoERG and LIT amounts are base units. New keys get added over\ntime, so ignore ones you do not recognise.\n\n| Key | Meaning |\n| --- | --- |\n| `chain.blocks`, `chain.difficultySum` | Ergo blocks processed, and the sum of their network difficulty. |\n| `chain.transactionFeeNanoErg` | Miner-fee outputs from every transaction in those blocks. |\n| `lithos.blocks`, `lithos.difficultySum` | Blocks carrying a configured Lithos genesis \u2014 counted once each \u2014 and their difficulty. |\n| `lithos.transactionFeeNanoErg` | Miner-fee outputs from the transactions inside those Lithos blocks. |\n| `local.payout.*` | Confirmed payouts to this client's primary mining address. |\n| `local.slashed.count`, `.bondNanoErg` | Fraud proofs that removed this client's own entry, and the bonds it lost. |\n| `network.payout.*` | Every payout seen for the configured protocol, local ones included. |\n| `collateral.consumedNanoErg` | Collateral spent by genesis transactions. Not income. |\n| `holding.genesisNanoErg` | Value placed in holding boxes at genesis. Contains the pool's share of any priority bid. |\n| `lithos.priorityFeeNanoErg` | Priority fees carried by the collateral boxes those blocks spent. |\n| `lithos.blocksWithPriorityFee` | How many of those blocks carried a fee at all. |\n| `collateral.<path>.*` | Lender cost and return by how the spent box was taken, `bid` or `clearance`: `boxes`, `priorityFeeNanoErg`, `costNanoErg`, `receivedNanoErg`, `waitBlocks`, and `capitalNanoErgBlocks`, the queue box's value times the blocks it stayed locked. `/stats/collateral` turns these into rates. |\n| `batching.<protocol>.*` | Executor fees earned filling `ergodex` or `lithosdex` orders, and builder takings from `forwards` recordings and settlements. |\n| `batching.<protocol>.tokens.<tokenId>`, `.otherTokens` | Tokens executors kept, by verified token id; `otherTokens` counts the times an unlisted token was kept, never its amount. |\n| `lithos.batching.<protocol>.*` | The same, counting only blocks that carried a Lithos genesis. |\n| `pool.batching.<protocol>.orders`, `.grossNanoErg` | Fee-less executions inside Lithos blocks. Their takings top up the rollup, so they reach miners through payouts. |\n| `local.batching.<protocol>.*` | Executions whose takings went to this client, outside the pool. Paid straight to its wallet, less the transaction fee. |\n| `local.received.<protocol>.tokens.<tokenId>`, `.otherTokens` | Tokens that reached this client's own address, in its own Lithos blocks too: a holding box never takes tokens, so they go to the block's finder. |\n| `rollup.<kind>.*` | Confirmed rollup transitions: `topUp`, `submission`, `evaluation`, `fraudProof`, `payoutReady`. |\n| `transaction.<kind>.count`, `.feeNanoErg` | Recognised transactions and the fees they paid. |\n| `registration.<kind>.count`, `.localCount` | Miner Dictionary `add`, `remove` and `evict` events. |\n\n**Payout families** hold `outputs`, `grossNanoErg`, `rewardNanoErg`, `bondNanoErg`,\n`surplusNanoErg`, `rewardLit` and `receivedLit`. Gross ERG is reward plus refunded bond plus\nany surplus. `rewardLit` is what the protocol owes; `receivedLit` is what the outputs actually\ncarried. Network totals already contain the local ones \u2014 never add the two together.\n\n**Batching families** hold `orders`, `grossNanoErg`, `transactionFeeNanoErg` and\n`afterTransactionFeesNanoErg`, counting recognised execution layouts only, not all pool\nactivity. Gross is newly earned executor fees and excludes takings carried in from earlier.\nLiquidity-provider fees are a different thing and live on the DEX API. `pool.batching` pays\nno transaction fee, so it holds only `orders` and `grossNanoErg`. It and `local.batching`\nnever count the same execution. A `forwards` recording broadcast alone pays its fee from the\nwallet for LIT, so its fee is above its gross: that part is `feeAboveGrossNanoErg`, and the net\nis `afterTransactionFeesNanoErg - feeAboveGrossNanoErg`. Token keys are named only for tokens\non the verified list when the execution was recorded; `tokens` in the response names each one.\n\n**Rollup families** hold `count`, `miners`, `claimedScore`, `bondNanoErg` and `valueNanoErg`,\nplus `localCount`, `localValueNanoErg`, `localBondNanoErg` and `localClaimedScore` where the\nlocal miner is identifiable \u2014 the submitting miner for submissions, the prover input for fraud\nproofs. So `rollup.submission.localBondNanoErg` is the bond this client posted, and\n`rollup.fraudProof.localValueNanoErg` is the slashed bonds it was paid for proving fraud. `miners` counts entries\nat that transition, not unique people. `valueNanoErg` means a different thing per kind:\nadded holding value for a top-up, zero for a submission, the full box value at evaluation,\nthe slashed bond for a fraud proof, and distributable ERG excluding bonds at payout readiness.\nThese are stages of the same funds, so summing them is not income.\n\n`transaction.<kind>` covers `genesis`, the rollup kinds above, `payout`, `registration`,\n`ergodex`, `lithosdex`, `forwards`, `ergodexOtherPoolSpend` and `lithosdexOtherPoolSpend`. Those fees\noverlap the block fee totals.\n\n**Priority fees.** `lithos.priorityFeeNanoErg / lithos.blocks` is the mean fee across every\nLithos block; divide by `lithos.blocksWithPriorityFee` instead for the mean across the blocks\nthat carried one. The amount is the WHOLE fee the lender posted, not the share the block's\nfinder keeps out of it. The pool's share went into the holding box and is already inside\n`holding.genesisNanoErg`, so there is deliberately no separate key for it.\n\nDivide a sum by its matching count for an average. `claimedScore` is protocol accounting,\nnot measured hashrate. A transaction fee is a transaction's cost and not automatically this\nclient's expense, holding top-ups and executor fees can describe the same proceeds, and no\nkey here is a net-income figure.\n",example:{"chain.blocks":"720","lithos.blocks":"12","local.payout.outputs":"3","local.payout.rewardNanoErg":"1500000000","local.payout.bondNanoErg":"3000000","batching.lithosdex.orders":"20","batching.lithosdex.grossNanoErg":"40000000"},title:"MiningAccountingMetrics"},tokens:{type:"object",description:"Every verified token a `.tokens.<tokenId>` key above names, by id, so each amount can be shown in whole units.",additionalProperties:{description:"A token on the client's verified list",type:"object","x-tags":"wallet",required:["tokenId","name","ticker","decimals"],properties:{tokenId:{type:"string",example:"c1980d829988229516430a47a5eca376060b6ce859616db0936e78ab25cb6de7"},name:{type:"string",example:"LIT"},ticker:{type:"string",example:"LIT"},decimals:{type:"integer",format:"int32",example:9}},title:"VerifiedToken"}}},title:"MiningTotalsResponse"}}}}}})]})}function k(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(w,{...e})}):w(e)}}}]);